discodex_platform_target() {
  case "$1:$2" in
    Linux:x86_64) printf '%s' 'x86_64-unknown-linux-gnu' ;;
    Linux:amd64) printf '%s' 'x86_64-unknown-linux-gnu' ;;
    Linux:aarch64) printf '%s' 'aarch64-unknown-linux-gnu' ;;
    Linux:arm64) printf '%s' 'aarch64-unknown-linux-gnu' ;;
    Darwin:x86_64) printf '%s' 'x86_64-apple-darwin' ;;
    Darwin:amd64) printf '%s' 'x86_64-apple-darwin' ;;
    Darwin:arm64) printf '%s' 'aarch64-apple-darwin' ;;
    Darwin:aarch64) printf '%s' 'aarch64-apple-darwin' ;;
    *) return 1 ;;
  esac
}
discodex_platform_asset() {
  case "$1:$2" in
    Linux:x86_64) printf '%s' 'discodex-x86_64-unknown-linux-gnu' ;;
    Linux:amd64) printf '%s' 'discodex-x86_64-unknown-linux-gnu' ;;
    Linux:aarch64) printf '%s' 'discodex-aarch64-unknown-linux-gnu' ;;
    Linux:arm64) printf '%s' 'discodex-aarch64-unknown-linux-gnu' ;;
    Darwin:x86_64) printf '%s' 'discodex-x86_64-apple-darwin' ;;
    Darwin:amd64) printf '%s' 'discodex-x86_64-apple-darwin' ;;
    Darwin:arm64) printf '%s' 'discodex-aarch64-apple-darwin' ;;
    Darwin:aarch64) printf '%s' 'discodex-aarch64-apple-darwin' ;;
    *) return 1 ;;
  esac
}
